# Tracks quote parity and turns the commas outside quoted text into periods
n=int(input())
s=input()
s=list(s)
cnt=0
for i in range(n):
    if s[i]=='"':
        cnt+=1
    if s[i]==",":
        if cnt%2==0:
            s[i]="."
ans=""
for i in range(n):
    ans+=s[i]
print(ans)

